#include "quadfield.h"

#include "quadfield_shaders.h" // generated by CMake from the .qsb files

#include <rhi/qshader.h>

#include <QtCore/QByteArray>
#include <QtCore/QList>

#include <cstring>

namespace srpss_spike {

namespace {

struct Uniforms
{
    float unitToClip[16];
    float params[4];
};
static_assert(sizeof(Uniforms) == 80, "std140 block layout");

QShader shaderFrom(const unsigned char *data, unsigned int size)
{
    return QShader::fromSerialized(
        QByteArray(reinterpret_cast<const char *>(data), int(size)));
}

QList<float> instanceData(int count)
{
    // Deterministic jittered grid so every backend and host draws the same dots.
    QList<float> out;
    out.reserve(count * 4);
    int side = 1;
    while (side * side < count)
        ++side;
    quint32 state = 0x9e3779b9u;
    auto next = [&state]() {
        state = state * 1664525u + 1013904223u;
        return float(state >> 8) / float(1u << 24);
    };
    for (int i = 0; i < count; ++i) {
        const float gx = (float(i % side) + 0.5f) / float(side);
        const float gy = (float(i / side) + 0.5f) / float(side);
        out << gx + (next() - 0.5f) * 0.6f / float(side)
            << gy + (next() - 0.5f) * 0.6f / float(side)
            << 0.35f / float(side) + next() * 0.25f / float(side)
            << float(i) * 0.6180339887f - float(int(float(i) * 0.6180339887f));
    }
    return out;
}

} // namespace

QuadField::QuadField(int instanceCount)
    : m_instances(instanceCount > 0 ? instanceCount : 1)
{
}

QuadField::~QuadField()
{
    release();
}

void QuadField::release()
{
    m_pipeline.reset();
    m_bindings.reset();
    m_uniforms.reset();
    m_instanceData.reset();
    m_corners.reset();
    m_renderPass.reset();
    m_rhi = nullptr;
}

bool QuadField::ensure(QRhi *rhi, QRhiRenderPassDescriptor *renderPass, int sampleCount,
                       QRhiResourceUpdateBatch *updates)
{
    if (!rhi || !renderPass)
        return false;
    if (m_rhi && m_rhi != rhi)
        release();

    if (!m_corners) {
        m_rhi = rhi;
        static const float corners[] = { -1.f, -1.f, 1.f, -1.f, -1.f, 1.f, 1.f, 1.f };
        m_corners.reset(rhi->newBuffer(QRhiBuffer::Immutable, QRhiBuffer::VertexBuffer,
                                       sizeof(corners)));
        const QList<float> inst = instanceData(m_instances);
        const quint32 instBytes = quint32(inst.size() * sizeof(float));
        m_instanceData.reset(rhi->newBuffer(QRhiBuffer::Immutable, QRhiBuffer::VertexBuffer,
                                            instBytes));
        m_uniforms.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer,
                                        sizeof(Uniforms)));
        if (!m_corners->create() || !m_instanceData->create() || !m_uniforms->create()) {
            release();
            return false;
        }
        updates->uploadStaticBuffer(m_corners.get(), corners);
        updates->uploadStaticBuffer(m_instanceData.get(), 0, instBytes, inst.constData());

        m_bindings.reset(rhi->newShaderResourceBindings());
        m_bindings->setBindings({ QRhiShaderResourceBinding::uniformBuffer(
            0, QRhiShaderResourceBinding::VertexStage | QRhiShaderResourceBinding::FragmentStage,
            m_uniforms.get()) });
        if (!m_bindings->create()) {
            release();
            return false;
        }
    }

    const bool compatible = m_renderPass && m_renderPass->isCompatible(renderPass)
        && m_sampleCount == sampleCount;
    if (!m_pipeline || !compatible)
        return createPipeline(renderPass, sampleCount);
    return true;
}

bool QuadField::createPipeline(QRhiRenderPassDescriptor *renderPass, int sampleCount)
{
    m_pipeline.reset();
    m_renderPass.reset(renderPass->newCompatibleRenderPassDescriptor());
    m_sampleCount = sampleCount;

    const QShader vs = shaderFrom(quadfield_vert_qsb, quadfield_vert_qsb_size);
    const QShader fs = shaderFrom(quadfield_frag_qsb, quadfield_frag_qsb_size);
    if (!vs.isValid() || !fs.isValid())
        return false;

    m_pipeline.reset(m_rhi->newGraphicsPipeline());
    QRhiGraphicsPipeline::TargetBlend blend;
    blend.enable = true;
    blend.srcColor = QRhiGraphicsPipeline::One;
    blend.dstColor = QRhiGraphicsPipeline::OneMinusSrcAlpha;
    blend.srcAlpha = QRhiGraphicsPipeline::One;
    blend.dstAlpha = QRhiGraphicsPipeline::OneMinusSrcAlpha;
    m_pipeline->setTargetBlends({ blend });
    m_pipeline->setTopology(QRhiGraphicsPipeline::TriangleStrip);
    m_pipeline->setSampleCount(sampleCount);
    m_pipeline->setShaderStages({ { QRhiShaderStage::Vertex, vs },
                                  { QRhiShaderStage::Fragment, fs } });
    QRhiVertexInputLayout layout;
    layout.setBindings({ { 2 * sizeof(float) },
                         { 4 * sizeof(float), QRhiVertexInputBinding::PerInstance } });
    layout.setAttributes({ { 0, 0, QRhiVertexInputAttribute::Float2, 0 },
                           { 1, 1, QRhiVertexInputAttribute::Float4, 0 } });
    m_pipeline->setVertexInputLayout(layout);
    m_pipeline->setShaderResourceBindings(m_bindings.get());
    m_pipeline->setRenderPassDescriptor(m_renderPass.get());
    if (!m_pipeline->create()) {
        m_pipeline.reset();
        return false;
    }
    return true;
}

void QuadField::update(QRhiResourceUpdateBatch *updates, const QMatrix4x4 &unitToClip,
                       float timeSeconds, float aspect)
{
    if (!m_uniforms)
        return;
    Uniforms u;
    std::memcpy(u.unitToClip, unitToClip.constData(), sizeof(u.unitToClip));
    u.params[0] = timeSeconds;
    u.params[1] = aspect > 0.f ? aspect : 1.f;
    u.params[2] = 0.f;
    u.params[3] = 0.f;
    updates->updateDynamicBuffer(m_uniforms.get(), 0, sizeof(Uniforms), &u);
}

void QuadField::record(QRhiCommandBuffer *cb, const QRhiViewport &viewport)
{
    if (!m_pipeline)
        return;
    cb->setGraphicsPipeline(m_pipeline.get());
    cb->setViewport(viewport);
    cb->setShaderResources();
    const QRhiCommandBuffer::VertexInput inputs[] = { { m_corners.get(), 0 },
                                                      { m_instanceData.get(), 0 } };
    cb->setVertexInput(0, 2, inputs);
    cb->draw(4, quint32(m_instances));
}

QMatrix4x4 unitToClipForRhi(QRhi *rhi)
{
    QMatrix4x4 m = rhi->clipSpaceCorrMatrix();
    QMatrix4x4 ortho;
    ortho.ortho(0.f, 1.f, 1.f, 0.f, -1.f, 1.f); // unit square, y down -> GL-style NDC
    return m * ortho;
}

} // namespace srpss_spike
